raw_chrome.base_css:
:root{--neon-blue: oklch(65% 0.3 260); --flame-red: oklch(60% 0.3 20); --carbon-base: oklch(15% 0.01 260); --glass-edge: rgba(255, 255, 255, 0.05);}
body{background-color: rgb(5, 5, 5); color: rgb(255, 255, 255); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; overflow-x: hidden; overscroll-behavior: none;}
::view-transition-old(root), ::view-transition-new(root){animation-duration: 0.8s; animation-timing-function: cubic-bezier(0.25, 1, 0, 1);}

raw_chrome.util_css:
.portal-container{position: fixed; inset: -10vh -10vw; z-index: 0; clip-path: polygon(0px 0px, 88% 8%, 100% 100%, 12% 92%); pointer-events: none; transform: scale(1.05);}
.portal-backdrop{position: absolute; inset: 0px; background: radial-gradient(circle, rgba(0, 0, 0, 0.1) 0%, rgba(5, 5, 5, 0.8) 60%, rgb(5, 5, 5) 100%);}
@keyframes kinetic-shimmer { 
  0% { background-position: 200% center; }
  100% { background-position: -200% center; }
}
.debossed-surface{background: linear-gradient(145deg, var(--carbon-base), #020202); box-shadow: rgba(0, 0, 0, 0.9) 3px 3px 8px inset, rgba(255, 255, 255, 0.03) -2px -2px 6px inset, rgba(0, 0, 0, 0.5) 0px 10px 30px; border-radius: 24px; position: relative; overflow: hidden;}
.debossed-surface::before{content: ""; position: absolute; inset: 0px; border-radius: inherit; padding: 1px; background: linear-gradient(135deg, rgba(255, 255, 255, 0.05) 0%, transparent 40%, transparent 60%, rgba(255, 255, 255, 0.02) 100%); mask: linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px) content-box exclude, linear-gradient(rgb(255, 255, 255) 0px, rgb(255, 255, 255) 0px); pointer-events: none;}
.glow-edge{position: absolute; inset: 0px; background: radial-gradient(circle at var(--x, 50%) var(--y, 50%), var(--neon-blue) 0%, transparent 50%); opacity: 0; transition: opacity 0.3s; mix-blend-mode: screen; pointer-events: none;}
.debossed-surface:hover .glow-edge{opacity: 0.15;}
@keyframes scroll-reveal { 
  0% { opacity: 0; transform: translateY(80px) scale(0.95); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}
.native-scroll-timeline{animation-duration: auto; animation-timing-function: linear; animation-delay: 0s; animation-iteration-count: 1; animation-direction: normal; animation-fill-mode: both; animation-play-state: running; animation-name: scroll-reveal; animation-timeline: view(); animation-range: entry 10% cover 30%;}
.bento-grid{display: grid; grid-template-columns: repeat(12, 1fr); grid-auto-rows: minmax(100px, auto); gap: 1.5rem;}
.col-span-8{grid-column: span 8;}
.col-span-4{grid-column: span 4;}
@media (max-width: 1024px){.col-span-8, .col-span-4{grid-column: span 12;}}

raw_chrome.header_css:
.text-kinetic{background-image: ; background-position-x: ; background-position-y: ; background-repeat: ; background-attachment: ; background-origin: ; background-color: ; background-size: 200% auto; color: transparent; background-clip: text; animation: 6s cubic-bezier(0.4, 0, 0.2, 1) 0s infinite normal none running kinetic-shimmer;}
.liquid-mercury-btn{background: linear-gradient(135deg, rgb(212, 212, 212) 0%, rgb(138, 138, 138) 50%, rgb(229, 229, 229) 100%); color: rgb(0, 0, 0); font-weight: 600; padding: 1rem 2.5rem; border-radius: 9999px; box-shadow: rgba(0, 0, 0, 0.5) 0px 10px 20px, rgba(255, 255, 255, 0.9) 0px 2px 4px inset, rgba(0, 0, 0, 0.3) 0px -2px 4px inset; transform-style: preserve-3d; transition: 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275); position: relative;}
.liquid-mercury-btn:hover{transform: translateY(-4px) translateZ(32px) scale(1.02); box-shadow: 0 25px 40px rgba(0,0,0,0.6), 
    0 0 30px var(--neon-blue), 
    inset 0 2px 4px rgba(255,255,255,0.9), 
    inset 0 -2px 4px rgba(0,0,0,0.3);}
